sql_query:
SELECT "Type of therapy"
FROM clinical_trials
WHERE LOWER(TRIM(COALESCE("Type of therapy", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Non-Small Cell Lung' AND TRIM(COALESCE("Included in MA", '')) = 'Yes' AND TRIM(COALESCE("Name of ICI", '')) = 'Atezolizumab';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Type of therapy" AS source_value FROM clinical_trials WHERE LOWER(TRIM(COALESCE("Type of therapy", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Non-Small Cell Lung' AND TRIM(COALESCE("Included in MA", '')) = 'Yes' AND TRIM(COALESCE("Name of ICI", '')) = 'Atezolizumab'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_is_combination(source_value) AS "is_combination"
FROM base;
